    for (const error of validateSchema.errors ?? []) errors.push({ code: 'SCHEMA', path: error.instancePath || '/', message: error.message ?? 'Schema validation failed' });
  } else errors.push(...semanticErrorsTrajectorySpec(document));
  return { valid: errors.length === 0, errors };
}

#!/usr/bin/env node

import { createHash } from 'node:crypto';
import { readFile, realpath, statfs } from 'node:fs/promises';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { compileBuildPlan } from './compile-build-plan.mjs';
import { evaluateDiskSpace, gibToBytes } from './lib/disk-space-guard.mjs';
import { runGit } from './lib/formal-run-admission.mjs';
import {
  canonicalJson,
  durableMkdir,
  repoUri,
  resolveExistingRepositoryPath,
  resolveFreshRepositoryPath,
  sha256File,
  writeDurableHashed,
} from './lib/production-compile-receipt.mjs';
import { repositoryRoot } from './lib/scene-spec.mjs';

const RELEASE_MANIFEST_URI = 'specs/production-compiler-entry.v0.2.json';

class PreflightError extends Error {
  constructor(reason, message) {
    super(message);
    this.name = 'PreflightError';
    this.reason = reason;
  }
}

function parseArguments(argv) {
  const parsed = {};
  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];
    if (token === '--scene-spec') parsed.sceneSpec = argv[++index];
    else if (token === '--preflight-root') parsed.preflightRoot = argv[++index];
    else if (token === '--output-root') parsed.outputRoot = argv[++index];
    else if (token === '--release-commit') parsed.releaseCommit = argv[++index];
    else throw new PreflightError('CLI_ARGUMENT', `Unknown or incomplete argument: ${token}`);
  }
  for (const required of ['sceneSpec', 'preflightRoot', 'outputRoot', 'releaseCommit']) {
    if (!parsed[required]) throw new PreflightError('CLI_ARGUMENT', `Missing --${required.replace(/[A-Z]/g, letter => `-${letter.toLowerCase()}`)}`);
  }
  if (!/^[0-9a-f]{40}$/.test(parsed.releaseCommit)) throw new PreflightError('RELEASE_COMMIT', 'Release commit must be a full lowercase SHA-1');
  return parsed;
}

async function gitRequired(args, gitChildren, reason, message) {
  const result = await runGit(args, repositoryRoot, row => gitChildren.push(row));
  if (result.exitCode !== 0) throw new PreflightError(reason, `${message}: ${result.stderr.trim()}`);
  return result.stdout.trim();
}

async function requireTrackedClean(uri, gitChildren) {
  await gitRequired(['ls-files', '--error-unmatch', '--', uri], gitChildren, 'TRACKED_CLEAN', `Untracked path ${uri}`);
  const dirty = await runGit(['status', '--porcelain=v1', '--untracked-files=all', '--', uri], repositoryRoot, row => gitChildren.push(row));
  if (dirty.exitCode !== 0 || dirty.stdout.length !== 0) throw new PreflightError('TRACKED_CLEAN', `Dirty path ${uri}`);
}

async function requireCommitPushed(commit, gitChildren) {
  const resolved = await gitRequired(['rev-parse', '--verify', `${commit}^{commit}`], gitChildren, 'RELEASE_COMMIT', 'Release commit is missing');
  if (resolved !== commit) throw new PreflightError('RELEASE_COMMIT', 'Release commit did not resolve exactly');
  await gitRequired(['rev-parse', '--verify', 'origin/main'], gitChildren, 'ORIGIN_BRANCH', 'origin/main is missing');
  const ancestor = await runGit(['merge-base', '--is-ancestor', commit, 'origin/main'], repositoryRoot, row => gitChildren.push(row));
  if (ancestor.exitCode !== 0) throw new PreflightError('RELEASE_NOT_PUSHED', 'Release commit is not an ancestor of origin/main');
}

async function requireBlobAtCommit(uri, expectedSha256, releaseCommit, gitChildren) {
  const shown = await runGit(['show', `${releaseCommit}:${uri}`], repositoryRoot, row => gitChildren.push(row));
  if (shown.exitCode !== 0) throw new PreflightError('RELEASE_BLOB', `Release commit does not contain ${uri}`);
  const currentPath = await resolveExistingRepositoryPath(uri, `Release path ${uri}`);
  const currentSha256 = await sha256File(currentPath);
  const commitSha256 = createHash('sha256').update(Buffer.from(shown.stdout)).digest('hex');
  if (currentSha256 !== expectedSha256 || commitSha256 !== expectedSha256) {
    throw new PreflightError('RELEASE_BLOB', `Release hash mismatch for ${uri}`);
  }
  return currentSha256;
}

async function sceneCommitIdentity(sceneUri, gitChildren) {
  const commit = await gitRequired(['log', '-1', '--format=%H', '--', sceneUri], gitChildren, 'SCENE_COMMIT', 'SceneSpec has no affecting commit');
  const ancestor = await runGit(['merge-base', '--is-ancestor', commit, 'origin/main'], repositoryRoot, row => gitChildren.push(row));
  if (ancestor.exitCode !== 0) throw new PreflightError('SCENE_NOT_PUSHED', 'SceneSpec affecting commit is not pushed to origin/main');
  return commit;
}

async function readReleaseManifest(releasePath) {
  const release = JSON.parse(await readFile(releasePath, 'utf8'));
  if (release.schemaVersion !== 'bfs.productionCompilerEntry.v0.2' || release.status !== 'RELEASE_CANDIDATE') {
    throw new PreflightError('RELEASE_MANIFEST', 'Production release manifest schema or status mismatch');
  }
  if (release.originRef !== 'origin/main' || release.preregistrationCommit !== 'c9e0b9e25c41b751fb456cf115e29e63996dbea4') {
    throw new PreflightError('RELEASE_MANIFEST', 'Production release manifest provenance mismatch');
  }
  return release;
}

async function evaluate(parsed) {
  const gitChildren = [];
  const releasePath = await resolveExistingRepositoryPath(RELEASE_MANIFEST_URI, 'Production release manifest');
  const scenePath = await resolveExistingRepositoryPath(parsed.sceneSpec, 'Production SceneSpec');
  const outputPath = await resolveFreshRepositoryPath(parsed.outputRoot, 'Production output root');
  const release = await readReleaseManifest(releasePath);
  if (repoUri(scenePath) !== parsed.sceneSpec || repoUri(outputPath) !== parsed.outputRoot) throw new PreflightError('PATH_SPELLING', 'Canonical repository-relative spelling mismatch');
  await requireCommitPushed(parsed.releaseCommit, gitChildren);

  const frozenHashes = { [RELEASE_MANIFEST_URI]: await sha256File(releasePath) };
  const trustedUris = [RELEASE_MANIFEST_URI, 'package.json', ...Object.keys(release.frozenFiles)].sort();
  for (const uri of trustedUris) await requireTrackedClean(uri, gitChildren);
  await requireTrackedClean(parsed.sceneSpec, gitChildren);
  for (const [uri, expectedSha256] of Object.entries(release.frozenFiles).sort(([left], [right]) => left.localeCompare(right))) {
    frozenHashes[uri] = await requireBlobAtCommit(uri, expectedSha256, parsed.releaseCommit, gitChildren);
  }
  const releaseCommitManifestSha = await requireBlobAtCommit(RELEASE_MANIFEST_URI, frozenHashes[RELEASE_MANIFEST_URI], parsed.releaseCommit, gitChildren);
  if (releaseCommitManifestSha !== frozenHashes[RELEASE_MANIFEST_URI]) throw new PreflightError('RELEASE_MANIFEST', 'Release manifest commit binding mismatch');
  const sceneSha256 = await sha256File(scenePath);
  const sceneCommit = await sceneCommitIdentity(parsed.sceneSpec, gitChildren);

  const first = await compileBuildPlan(parsed.sceneSpec);
  const second = await compileBuildPlan(parsed.sceneSpec);
  const buildPlanCanonicalExact = canonicalJson(first) === canonicalJson(second);
  if (!buildPlanCanonicalExact) throw new PreflightError('BUILD_PLAN_IDENTITY', 'Repeated in-memory BuildPlan bytes differ');

  const filesystem = await statfs(repositoryRoot, { bigint: true });
  const observedAvailableBytes = filesystem.bavail * filesystem.bsize;
  const ceilingText = process.env.BFS_PRODUCTION_PREFLIGHT_AVAILABLE_BYTES_CEILING;
  const ceilingBytes = ceilingText === undefined ? null : BigInt(ceilingText);
  if (ceilingBytes !== null && (ceilingBytes < 0n || ceilingBytes > observedAvailableBytes)) {
    throw new PreflightError('DISK_TEST_CEILING', 'Available-byte ceiling may only lower the real observation');
  }
  const effectiveAvailableBytes = ceilingBytes === null ? observedAvailableBytes : ceilingBytes;
  const disk = evaluateDiskSpace({
    availableBytes: effectiveAvailableBytes,
    capacityBytes: filesystem.blocks * filesystem.bsize,
    reserveBytes: gibToBytes(100),
    projectedWriteBytes: gibToBytes(0.5),
    target: repositoryRoot,
  });
  if (disk.status !== 'PASS') throw new PreflightError('DISK_ADMISSION', 'Projected production compile violates the frozen disk reserve');
  const nodePath = await realpath(process.execPath);
  const blenderPath = '/Applications/Blender.app/Contents/MacOS/Blender';
  const runtime = {
    node: { executable: nodePath, version: process.version, sha256: await sha256File(nodePath) },
    blender: { executable: blenderPath, sha256: await sha256File(blenderPath), buildHash: release.runtime.blender.buildHash, processStarted: false },
  };
  if (runtime.node.sha256 !== release.runtime.node.sha256 || runtime.node.version !== release.runtime.node.version
    || runtime.blender.sha256 !== release.runtime.blender.sha256) throw new PreflightError('RUNTIME_IDENTITY', 'Runtime identity mismatch');

  return {
    status: 'ACCEPTED',
    release: { uri: RELEASE_MANIFEST_URI, sha256: frozenHashes[RELEASE_MANIFEST_URI], releaseId: release.releaseId, releaseCommit: parsed.releaseCommit },
    invocation: { sceneSpec: parsed.sceneSpec, preflightRoot: parsed.preflightRoot, outputRoot: parsed.outputRoot },
    source: { uri: parsed.sceneSpec, sha256: sceneSha256, affectingCommit: sceneCommit },
    output: { repositoryRelative: parsed.outputRoot, absolutePathRecorded: false, absent: true },
    buildPlan: { planHash: first.planHash, planVersion: first.planVersion, canonicalPairExact: true, sourceSceneCanonicalSha256: first.plan.source.canonicalSha256 },
    runtime,
    disk: { ...disk, filesystemAvailableBytesObserved: observedAvailableBytes.toString(), effectiveAvailableBytes: effectiveAvailableBytes.toString(), testCeilingApplied: ceilingBytes !== null },
    toolHashes: Object.fromEntries(Object.entries(frozenHashes).sort(([left], [right]) => left.localeCompare(right))),
    git: { originRef: 'origin/main', gitChildren },
    operations: { blenderProcesses: 0, renderCalls: 0, modelCalls: 0, networkCalls: 0, dockerProcesses: 0 },
  };
}

export async function runProductionPreflight(argv) {
  const parsed = parseArguments(argv);
  const rootSpellings = [parsed.preflightRoot, parsed.outputRoot];
  if (rootSpellings.some((left, index) => rootSpellings.some((right, other) => index !== other && (left === right || left.startsWith(`${right}/`) || right.startsWith(`${left}/`))))) {
    throw new Error('Production preflight and output roots must be disjoint');
  }
  const preflightPath = await resolveFreshRepositoryPath(parsed.preflightRoot, 'Production preflight root');
  let body;
  try {
    body = { schemaVersion: 'bfs.productionCompilePreflight.v0.1', ...(await evaluate(parsed)), reason: null };
  } catch (error) {
    body = {
      schemaVersion: 'bfs.productionCompilePreflight.v0.1',
      status: 'REJECTED',
      reason: error instanceof PreflightError ? error.reason : 'PREFLIGHT_EXCEPTION',
      message: error?.message ?? String(error),
      invocation: { sceneSpec: parsed.sceneSpec, preflightRoot: parsed.preflightRoot, outputRoot: parsed.outputRoot, releaseCommit: parsed.releaseCommit },
      toolHashes: {},
      operations: { blenderProcesses: 0, renderCalls: 0, modelCalls: 0, networkCalls: 0, dockerProcesses: 0 },
    };
  }
  await durableMkdir(preflightPath);
  const record = await writeDurableHashed(resolve(preflightPath, 'preflight.json'), body, 'preflightHash');
  process.stdout.write(`BFS_PRODUCTION_PREFLIGHT ${record.status} ${record.reason ?? record.buildPlan?.planHash ?? 'OK'}\n`);
  if (record.status !== 'ACCEPTED') process.exitCode = 1;
  return record;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  runProductionPreflight(process.argv.slice(2)).catch(error => {
    process.stderr.write(`BFS_PRODUCTION_PREFLIGHT_ERROR ${error.message}\n`);
    process.exitCode = 1;
  });
}

#!/usr/bin/env node
import { spawn } from 'node:child_process';
import { resolve } from 'node:path';
import { checkDiskSpace } from './lib/disk-space-guard.mjs';

const [script, ...args] = process.argv.slice(2);

if (!script) {
  process.stderr.write('Usage: node scripts/run-guarded-node.mjs <script> [args...]\n');
  process.exitCode = 64;
} else {
  const guard = await checkDiskSpace({ target: process.cwd() });
  process.stdout.write(`${JSON.stringify(guard)}\n`);

  if (guard.status === 'BLOCKED') {
    process.stderr.write('BFS_DISK_GUARD_BLOCKED: reclaim space or explicitly revise the reserve/projection policy before running this job.\n');
    process.exitCode = 75;
  } else {
    const child = spawn(process.execPath, [resolve(script), ...args], {
      cwd: process.cwd(),
      env: process.env,
      stdio: 'inherit',
    });
    child.on('error', error => {
      process.stderr.write(`BFS_GUARDED_RUN_ERROR ${error.message}\n`);
      process.exitCode = 70;
    });
    child.on('close', (code, signal) => {
      if (signal) {
        process.stderr.write(`BFS_GUARDED_RUN_SIGNAL ${signal}\n`);
        process.exitCode = 70;
      } else {
        process.exitCode = code ?? 70;
      }
    });
  }
}

#!/usr/bin/env node

import { createHash } from 'node:crypto';
import { spawn } from 'node:child_process';
import { readFile, readdir, rmdir, statfs } from 'node:fs/promises';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { compileBuildPlan } from './compile-build-plan.mjs';
import { AdmissionError, admitFormalRun } from './lib/formal-run-admission.mjs';
import { evaluateDiskSpace, gibToBytes } from './lib/disk-space-guard.mjs';
import {
  canonicalJson,
  createProductionCompileReceipt,
  durableMkdir,
  repoUri,
  resolveExistingRepositoryPath,
  resolveFreshRepositoryPath,
  sha256File,
  validSelfHash,
  writeDurableHashed,
  writeDurableJson,
} from './lib/production-compile-receipt.mjs';
import { repositoryRoot } from './lib/scene-spec.mjs';

const RELEASE_MANIFEST_URI = 'specs/production-compiler-entry.v0.2.json';
const RESTRICTED_CLI_URI = 'scripts/run-restricted-blender-compile.mjs';

function parseArguments(argv) {
  const parsed = {};
  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];
    if (token === '--scene-spec') parsed.sceneSpec = argv[++index];
    else if (token === '--preflight-root') parsed.preflightRoot = argv[++index];
    else if (token === '--attempt-root') parsed.attemptRoot = argv[++index];
    else if (token === '--output-root') parsed.outputRoot = argv[++index];
    else if (token === '--preflight-evidence-commit') parsed.preflightEvidenceCommit = argv[++index];
    else throw new Error(`Unknown or incomplete argument: ${token}`);
  }
  for (const required of ['sceneSpec', 'preflightRoot', 'attemptRoot', 'outputRoot', 'preflightEvidenceCommit']) {
    if (!parsed[required]) throw new Error(`Missing --${required.replace(/[A-Z]/g, letter => `-${letter.toLowerCase()}`)}`);
  }
  if (!/^[0-9a-f]{40}$/.test(parsed.preflightEvidenceCommit)) throw new Error('Preflight evidence commit must be a full lowercase SHA-1');
  return parsed;
}

async function runChild(command, args) {
  const started = process.hrtime.bigint();
  const child = spawn(command, args, {
    cwd: repositoryRoot,
    env: {
      PATH: '/opt/homebrew/bin:/usr/bin:/bin',
      LANG: 'C.UTF-8',
      LC_ALL: 'C.UTF-8',
      BLENDER_BIN: '/Applications/Blender.app/Contents/MacOS/Blender',
    },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  const stdout = [];
  const stderr = [];
  let stdoutBytes = 0;
  let stderrBytes = 0;
  const maximumLogBytes = 4 * 1024 * 1024;
  child.stdout.on('data', chunk => {
    stdoutBytes += chunk.length;
    if (stdoutBytes <= maximumLogBytes) stdout.push(chunk);
  });
  child.stderr.on('data', chunk => {
    stderrBytes += chunk.length;
    if (stderrBytes <= maximumLogBytes) stderr.push(chunk);
  });
  const completion = await new Promise((resolvePromise, reject) => {
    child.on('error', reject);
    child.on('close', (exitCode, signal) => resolvePromise({ exitCode, signal }));
  });
  const stdoutBuffer = Buffer.concat(stdout);
  const stderrBuffer = Buffer.concat(stderr);
  return {
    pid: child.pid,
    ...completion,
    elapsedNanoseconds: Number(process.hrtime.bigint() - started),
    stdout: { bytes: stdoutBytes, capturedBytes: stdoutBuffer.length, sha256: createHash('sha256').update(stdoutBuffer).digest('hex') },
    stderr: { bytes: stderrBytes, capturedBytes: stderrBuffer.length, sha256: createHash('sha256').update(stderrBuffer).digest('hex') },
    stdoutText: stdoutBuffer.toString('utf8'),
    stderrText: stderrBuffer.toString('utf8'),
  };
}

async function readAcceptedPreflight(preflightRoot, parsed) {
  const preflightPath = resolve(preflightRoot, 'preflight.json');
  const preflight = JSON.parse(await readFile(preflightPath, 'utf8'));
  if (!validSelfHash(preflight, 'preflightHash')) throw new Error('Production preflight self-hash mismatch');
  if (preflight.schemaVersion !== 'bfs.productionCompilePreflight.v0.1' || preflight.status !== 'ACCEPTED') throw new Error('Production preflight is not accepted');
  if (preflight.invocation?.sceneSpec !== parsed.sceneSpec || preflight.invocation?.preflightRoot !== parsed.preflightRoot
    || preflight.invocation?.outputRoot !== parsed.outputRoot || preflight.output?.repositoryRelative !== parsed.outputRoot) {
    throw new Error('Production preflight invocation binding mismatch');
  }
  return { preflightPath, preflight };
}

async function writeAdmissionFailure(attemptRoot, attemptPath, attempt, error, gitChildren) {
  const failurePath = resolve(attemptRoot, 'failure.json');
  const failure = await writeDurableHashed(failurePath, {
    schemaVersion: 'bfs.productionCompileAdmissionFailure.v0.1',
    sequence: 2,
    status: 'REJECTED',
    reason: error instanceof AdmissionError ? error.reason : 'ADMISSION_EXCEPTION',
    message: error?.message ?? String(error),
    attempt: { uri: repoUri(attemptPath), sha256: await sha256File(attemptPath), attemptHash: attempt.attemptHash },
    gitChildren,
    outputMaterialized: false,
    blenderProcessesStarted: 0,
    scientificVerdict: null,
  }, 'failureHash');
  await writeDurableHashed(resolve(attemptRoot, 'receipt.json'), {
    schemaVersion: 'bfs.productionCompileAttemptReceipt.v0.1',
    sequence: 3,
    status: 'REJECTED',
    scientificVerdict: null,
    attempt: { uri: repoUri(attemptPath), sha256: await sha256File(attemptPath), attemptHash: attempt.attemptHash },
    failure: { uri: repoUri(failurePath), sha256: await sha256File(failurePath), failureHash: failure.failureHash },
    outputMaterialized: false,
    compilerProcessesStarted: 0,
  }, 'receiptHash');
}

async function writeInvalidation(outputRoot, phase, error, context = {}) {
  const invalidationPath = resolve(outputRoot, 'invalidation.json');
  try {
    await writeDurableHashed(invalidationPath, {
      schemaVersion: 'bfs.productionCompileInvalidation.v0.1',
      status: 'INVALIDATED',
      phase,
      error: { name: error?.name ?? 'Error', message: error?.message ?? String(error) },
      context,
      partialEvidenceRetained: true,
      scientificVerdict: null,
    }, 'invalidationHash');
  } catch (writeError) {
    if (writeError?.code !== 'EEXIST') throw writeError;
  }
}

async function writeNativeCompileDiskAdmission(outputRoot) {
  const filesystem = await statfs(repositoryRoot, { bigint: true });
  const observedAvailableBytes = filesystem.bavail * filesystem.bsize;
  const ceilingText = process.env.BFS_PRODUCTION_COMPILE_AVAILABLE_BYTES_CEILING;
  let ceilingBytes = null;
  let invalidCeiling = false;
  if (ceilingText !== undefined) {
    if (!/^[0-9]+$/.test(ceilingText)) invalidCeiling = true;
    else {
      ceilingBytes = BigInt(ceilingText);
      if (ceilingBytes > observedAvailableBytes) invalidCeiling = true;
    }
  }
  const effectiveAvailableBytes = invalidCeiling || ceilingBytes === null ? observedAvailableBytes : ceilingBytes;
  const disk = evaluateDiskSpace({
    availableBytes: effectiveAvailableBytes,
    capacityBytes: filesystem.blocks * filesystem.bsize,
    reserveBytes: gibToBytes(100),
    projectedWriteBytes: gibToBytes(0.5),
    target: repositoryRoot,
  });
  const accepted = !invalidCeiling && disk.status === 'PASS';
  return writeDurableHashed(resolve(outputRoot, 'native-compile-disk-admission.json'), {
    schemaVersion: 'bfs.productionNativeCompileDiskAdmission.v0.1',
    sequence: 5,
    status: accepted ? 'ACCEPTED' : 'REJECTED',
    reason: invalidCeiling ? 'TEST_CEILING_MAY_ONLY_LOWER_REAL_OBSERVATION' : disk.reason,
    filesystemAvailableBytesObserved: observedAvailableBytes.toString(),
    effectiveAvailableBytes: effectiveAvailableBytes.toString(),
    testCeilingApplied: ceilingBytes !== null && !invalidCeiling,
    disk,
    policy: { minimumReserveBytes: gibToBytes(100).toString(), projectedWriteBytes: gibToBytes(0.5).toString(), overrideAllowedByReleaseEntry: false },
    restrictedCompilerProcessesStarted: 0,
    nativeBlenderProcessesStarted: 0,
  }, 'diskAdmissionHash');
}

export async function runProductionCompile(argv) {
  const parsed = parseArguments(argv);
  const sceneSpecPath = await resolveExistingRepositoryPath(parsed.sceneSpec, 'Production SceneSpec');
  const preflightRoot = await resolveExistingRepositoryPath(parsed.preflightRoot, 'Production preflight root', 'directory');
  const attemptRoot = await resolveFreshRepositoryPath(parsed.attemptRoot, 'Production attempt root');
  const outputRoot = await resolveFreshRepositoryPath(parsed.outputRoot, 'Production output root');
  const releaseManifestPath = await resolveExistingRepositoryPath(RELEASE_MANIFEST_URI, 'Production release manifest');
  const rootSpellings = [parsed.preflightRoot, parsed.attemptRoot, parsed.outputRoot];
  if (rootSpellings.some((left, index) => rootSpellings.some((right, other) => index !== other && (left === right || left.startsWith(`${right}/`) || right.startsWith(`${left}/`))))) {
    throw new Error('Production preflight, attempt and output roots must be disjoint');
  }
  const preflightPath = await resolveExistingRepositoryPath(`${parsed.preflightRoot}/preflight.json`, 'Production preflight record');

  await durableMkdir(attemptRoot);
  const attemptPath = resolve(attemptRoot, 'attempt.json');
  const attempt = await writeDurableHashed(attemptPath, {
    schemaVersion: 'bfs.productionCompileAttempt.v0.1',
    sequence: 1,
    invocation: parsed,
    preflight: { uri: repoUri(preflightPath), sha256: await sha256File(preflightPath) },
    runnerPid: process.pid,
    outputAbsentBeforeAdmission: true,
    blenderProcessesAuthorized: 0,
    scientificVerdict: null,
  }, 'attemptHash');

  const gitChildren = [];
  let admission;
  let preflight;
  try {
    ({ preflight } = await readAcceptedPreflight(preflightRoot, parsed));
    if (await sha256File(sceneSpecPath) !== preflight.source.sha256) throw new AdmissionError('SCENE_BINDING', 'Production SceneSpec changed after preflight');
    if (await sha256File(releaseManifestPath) !== preflight.release.sha256) throw new AdmissionError('RELEASE_BINDING', 'Production release manifest changed after preflight');
    admission = await admitFormalRun({
      repositoryRoot,
      evidenceInput: parsed.preflightRoot,
      formalOutput: parsed.outputRoot,
      originRef: 'origin/main',
      gitObserver: row => gitChildren.push(row),
    });
    if (admission.evidence.evidenceCommit !== parsed.preflightEvidenceCommit) {
      throw new AdmissionError('EVIDENCE_COMMIT_MISMATCH', 'Preflight evidence commit differs from the CLI binding');
    }
    if (admission.output.repositoryRelative !== parsed.outputRoot) throw new AdmissionError('PREFLIGHT_BINDING', 'Production preflight output binding mismatch');
  } catch (error) {
    await writeAdmissionFailure(attemptRoot, attemptPath, attempt, error, gitChildren);
    process.stdout.write(`BFS_PRODUCTION_COMPILE REJECTED ${error.reason ?? 'ADMISSION_EXCEPTION'} blender=0\n`);
    process.exitCode = 1;
    return { status: 'REJECTED', reason: error.reason ?? 'ADMISSION_EXCEPTION' };
  }

  const admissionPath = resolve(attemptRoot, 'admission.json');
  const admissionRecord = await writeDurableHashed(admissionPath, {
    schemaVersion: 'bfs.productionCompileAdmission.v0.1',
    sequence: 2,
    status: 'ACCEPTED',
    evidence: admission.evidence,
    output: { repositoryRelative: admission.output.repositoryRelative, parentRepositoryRelative: admission.output.parentRepositoryRelative, fresh: admission.output.fresh },
    attempt: { uri: repoUri(attemptPath), sha256: await sha256File(attemptPath), attemptHash: attempt.attemptHash },
    gitChildren,
    compilerProcessesStarted: 0,
    scientificVerdict: null,
  }, 'admissionHash');
  const attemptReceiptPath = resolve(attemptRoot, 'receipt.json');
  const attemptReceipt = await writeDurableHashed(attemptReceiptPath, {
    schemaVersion: 'bfs.productionCompileAttemptReceipt.v0.1',
    sequence: 3,
    status: 'ACCEPTED',
    attempt: { uri: repoUri(attemptPath), sha256: await sha256File(attemptPath), attemptHash: attempt.attemptHash },
    admission: { uri: repoUri(admissionPath), sha256: await sha256File(admissionPath), admissionHash: admissionRecord.admissionHash },
    formalOutput: admissionRecord.output,
    outputMaterializationAuthorized: true,
    scientificVerdict: null,
  }, 'receiptHash');

  let phase = 'OUTPUT_MATERIALIZATION';
  try {
    await durableMkdir(outputRoot);
    const formalStartPath = resolve(outputRoot, 'formal-start.json');
    await writeDurableHashed(formalStartPath, {
      schemaVersion: 'bfs.productionCompileFormalStart.v0.1',
      sequence: 4,
      status: 'AUTHORIZED',
      attemptReceipt: { uri: repoUri(attemptReceiptPath), sha256: await sha256File(attemptReceiptPath), receiptHash: attemptReceipt.receiptHash },
      outputRoot: parsed.outputRoot,
      compilerProcessesStarted: 0,
    }, 'formalStartHash');

    phase = 'BUILD_PLAN';
    const first = await compileBuildPlan(parsed.sceneSpec);
    const second = await compileBuildPlan(parsed.sceneSpec);
    if (canonicalJson(first) !== canonicalJson(second) || first.planHash !== preflight.buildPlan.planHash) {
      throw new Error('Production BuildPlan no longer matches accepted preflight');
    }
    const planPath = resolve(outputRoot, 'build-plan.json');
    await writeDurableJson(planPath, first);

    phase = 'NATIVE_COMPILE_DISK_ADMISSION';
    const diskAdmissionPath = resolve(outputRoot, 'native-compile-disk-admission.json');
    const diskAdmission = await writeNativeCompileDiskAdmission(outputRoot);
    if (diskAdmission.status !== 'ACCEPTED') throw new Error(`Native compile disk admission rejected: ${diskAdmission.reason}`);

    phase = 'RESTRICTED_COMPILE';
    const restrictedRoot = resolve(outputRoot, 'restricted');
    const wrapper = await runChild(process.execPath, [
      resolve(repositoryRoot, RESTRICTED_CLI_URI),
      '--plan', planPath,
      '--output-dir', restrictedRoot,
      '--report', resolve(restrictedRoot, 'budget.report.json'),
      '--receipt', resolve(restrictedRoot, 'compile-receipt.json'),
    ]);
    const wrapperProcess = {
      pid: wrapper.pid,
      exitCode: wrapper.exitCode,
      signal: wrapper.signal,
      elapsedNanoseconds: wrapper.elapsedNanoseconds,
      stdout: wrapper.stdout,
      stderr: wrapper.stderr,
    };
    if (wrapper.exitCode !== 0 || wrapper.signal !== null) {
      throw new Error(`Restricted compiler failed: ${wrapper.stderrText || wrapper.stdoutText}`);
    }
    const emptyFramesPath = resolve(restrictedRoot, 'frames');
    const frameEntries = await readdir(emptyFramesPath).catch(error => {
      if (error?.code === 'ENOENT') return null;
      throw error;
    });
    if (frameEntries && frameEntries.length > 0) throw new Error('Zero-render production compile emitted frame files');
    if (frameEntries) await rmdir(emptyFramesPath);
    wrapperProcess.emptyFramesDirectoryRemoved = frameEntries !== null;

    phase = 'PRODUCTION_RECEIPT';
    const productionReceipt = await createProductionCompileReceipt({
      releaseManifestPath,
      releaseCommit: preflight.release.releaseCommit,
      preflightPath,
      attemptPath,
      admissionPath,
      attemptReceiptPath,
      formalStartPath,
      diskAdmissionPath,
      sceneSpecPath,
      planPath,
      restrictedRoot,
      wrapperProcess,
    });
    await writeDurableJson(resolve(outputRoot, 'production-receipt.json'), productionReceipt);
    process.stdout.write(`BFS_PRODUCTION_COMPILE PASS ${productionReceipt.buildPlan.planHash} ${productionReceipt.restrictedCompile.sceneStructureCanonical.structureHash} ${productionReceipt.receiptHash}\n`);
    return { status: 'PASS', receipt: productionReceipt };
  } catch (error) {
    await writeInvalidation(outputRoot, phase, error, { attemptHash: attempt.attemptHash, admissionHash: admissionRecord.admissionHash });
    process.stderr.write(`BFS_PRODUCTION_COMPILE_INVALIDATED ${phase} ${error.message}\n`);
    process.exitCode = 1;
    return { status: 'INVALIDATED', phase, reason: error.message };
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  runProductionCompile(process.argv.slice(2)).catch(error => {
    process.stderr.write(`BFS_PRODUCTION_COMPILE_ERROR ${error.message}\n`);
    process.exitCode = 1;
  });
}

import { access, mkdir, readFile, readdir, realpath, writeFile } from 'node:fs/promises';
import { constants } from 'node:fs';
import { createHash } from 'node:crypto';
import { dirname, relative, resolve, sep } from 'node:path';
import { pathToFileURL } from 'node:url';
import { repositoryRoot } from './lib/scene-spec.mjs';
import { runBudgetedProcess } from './lib/budgeted-process.mjs';
import { createCompileReceipt } from './lib/compile-receipt.mjs';

const profilePath = resolve(repositoryRoot, 'specs/restricted-compile-budget.v0.1.json');
const repositoryRealRoot = await realpath(repositoryRoot);

function assertBelowRepository(absolutePath, label) {
  const pathFromRoot = relative(repositoryRoot, absolutePath);
  if (pathFromRoot === '' || pathFromRoot === '..' || pathFromRoot.startsWith(`..${sep}`)) throw new Error(`${label} must resolve below the repository root`);
}

function assertBelowRealRepository(actualPath, label, allowRoot = false) {
  const pathFromRoot = relative(repositoryRealRoot, actualPath);
  if ((!allowRoot && pathFromRoot === '') || pathFromRoot === '..' || pathFromRoot.startsWith(`..${sep}`)) throw new Error(`${label} resolves outside the repository root`);
}

async function assertTrustedExistingPath(absolutePath, label) {
  assertBelowRepository(absolutePath, label);
  const actualPath = await realpath(absolutePath).catch(() => { throw new Error(`${label} is missing`); });
  assertBelowRealRepository(actualPath, label);
  if (actualPath !== absolutePath) throw new Error(`${label} must not traverse symbolic links`);
  return actualPath;
}

async function assertTrustedOutputPath(absolutePath, label) {
  assertBelowRepository(absolutePath, label);
  let probe = absolutePath;
  let actualPath = null;
  while (!actualPath) {
    actualPath = await realpath(probe).catch(error => {
      if (error?.code !== 'ENOENT') throw error;
      const parent = dirname(probe);
      if (parent === probe) throw error;
      probe = parent;
      return null;
    });
  }
  assertBelowRealRepository(actualPath, label, probe === repositoryRoot);
  if (actualPath !== probe) throw new Error(`${label} must not traverse symbolic links`);
}

async function findBlender() {
  const candidates = [process.env.BLENDER_BIN, '/Applications/Blender.app/Contents/MacOS/Blender', 'blender'].filter(Boolean);
  for (const candidate of candidates) {
    if (candidate === 'blender') return candidate;
    try { await access(candidate, constants.X_OK); return candidate; } catch {}
  }
  throw new Error('Blender executable not found; set BLENDER_BIN');
}

export async function runRestrictedCompile({ plan, outputDir }) {
  const blender = await findBlender();
  const profileBytes = await readFile(profilePath);
  const budgets = JSON.parse(profileBytes);
  const compiler = resolve(repositoryRoot, 'blender/compile_scene.py');
  const ocio = resolve(repositoryRoot, 'color/ocio/cg-config-v4.0.0_aces-v2.0_ocio-v2.5.ocio');
  const trustedPlan = await assertTrustedExistingPath(resolve(plan), 'BuildPlan');
  const trustedOutput = resolve(outputDir);
  await assertTrustedOutputPath(trustedOutput, 'Restricted compile output');
  const existingEntries = await readdir(trustedOutput).catch(error => {
    if (error?.code === 'ENOENT') return [];
    throw error;
  });
  if (existingEntries.length > 0) throw new Error(`Restricted compile output must be empty: found ${existingEntries.sort().join(', ')}`);
  await mkdir(trustedOutput, { recursive: true });
  const result = await runBudgetedProcess({
    command: blender,
    args: ['--background', '--factory-startup', '--disable-autoexec', '--python-exit-code', '1', '--python', compiler, '--', '--plan', trustedPlan, '--repository-root', repositoryRoot, '--output-dir', trustedOutput],
    cwd: repositoryRoot, env: { ...process.env, OCIO: ocio }, outputRoot: trustedOutput, budgets,
  });
  return { ...result, budgetProfile: { uri: 'specs/restricted-compile-budget.v0.1.json', sha256: createHash('sha256').update(profileBytes).digest('hex') } };
}

async function main() {
  const args = process.argv.slice(2);
  const option = name => { const index = args.indexOf(name); return index >= 0 ? args[index + 1] : null; };
  const plan = option('--plan');
  const outputDir = option('--output-dir');
  const report = option('--report');
  const receipt = option('--receipt');
  if (!plan || !outputDir || !report || !receipt) throw new Error('Usage: --plan FILE --output-dir DIR --report FILE --receipt FILE');
  const trustedReport = resolve(report);
  const trustedReceipt = resolve(receipt);
  await assertTrustedOutputPath(trustedReport, 'Restricted compile report');
  await assertTrustedOutputPath(trustedReceipt, 'CompileReceipt output');
  if (trustedReport === trustedReceipt) throw new Error('Restricted compile report and CompileReceipt output must be different files');
  const result = await runRestrictedCompile({ plan, outputDir });
  await writeFile(trustedReport, `${JSON.stringify(result, null, 2)}\n`);
  let compileReceipt = null;
  if (result.outcome === 'PASS') {
    compileReceipt = await createCompileReceipt({ planPath: resolve(plan), outputDir: resolve(outputDir), budgetReportPath: trustedReport, budgetResult: result });
    await writeFile(trustedReceipt, `${JSON.stringify(compileReceipt, null, 2)}\n`);
  }
  process.stdout.write(`BFS_RESTRICTED_COMPILE ${result.outcome} ${result.breach?.reason ?? 'WITHIN_BUDGET'}${compileReceipt ? ` ${compileReceipt.receiptHash}` : ''}\n`);
  if (result.outcome !== 'PASS') process.exitCode = 1;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch(error => { process.stderr.write(`BFS_RESTRICTED_COMPILE_ERROR ${error.message}\n`); process.exitCode = 1; });
}

import { access, readFile, realpath, stat, writeFile } from 'node:fs/promises';
import { constants } from 'node:fs';
import { execFile } from 'node:child_process';
import { dirname, relative, resolve, sep } from 'node:path';
import { pathToFileURL } from 'node:url';
import { isDeepStrictEqual } from 'node:util';
import { repositoryRoot } from './lib/scene-spec.mjs';
import { canonicalJson, sha256Canonical, sha256Bytes, sha256File } from './lib/receipt-format.mjs';

const repositoryRealRoot = await realpath(repositoryRoot);

async function trustedRepositoryFile(uri, label) {
  if (typeof uri !== 'string' || uri.length === 0) throw new Error(`${label} URI is missing`);
  const absolutePath = resolve(repositoryRoot, uri);
  const pathFromRoot = relative(repositoryRoot, absolutePath);
  if (pathFromRoot === '' || pathFromRoot === '..' || pathFromRoot.startsWith(`..${sep}`)) throw new Error(`${label} URI resolves outside repository`);
  const actualPath = await realpath(absolutePath).catch(() => { throw new Error(`${label} file is missing`); });
  const realFromRoot = relative(repositoryRealRoot, actualPath);
  if (realFromRoot === '' || realFromRoot === '..' || realFromRoot.startsWith(`..${sep}`)) throw new Error(`${label} real path escapes repository`);
  if (actualPath !== absolutePath) throw new Error(`${label} URI traverses symbolic links`);
  return actualPath;
}

async function trustedRepositoryOutput(path, label) {
  const absolutePath = resolve(path);
  const pathFromRoot = relative(repositoryRoot, absolutePath);
  if (pathFromRoot === '' || pathFromRoot === '..' || pathFromRoot.startsWith(`..${sep}`)) throw new Error(`${label} must resolve below repository`);
  let probe = absolutePath;
  let actualPath = null;
  while (!actualPath) {
    actualPath = await realpath(probe).catch(error => {
      if (error?.code !== 'ENOENT') throw error;
      const parent = dirname(probe);
      if (parent === probe) throw error;
      probe = parent;
      return null;
    });
  }
  const realFromRoot = relative(repositoryRealRoot, actualPath);
  if ((probe !== repositoryRoot && realFromRoot === '') || realFromRoot === '..' || realFromRoot.startsWith(`..${sep}`)) throw new Error(`${label} real path escapes repository`);
  if (actualPath !== probe) throw new Error(`${label} must not traverse symbolic links`);
  return absolutePath;
}

async function findBlender() {
  const candidates = [process.env.BLENDER_BIN, '/Applications/Blender.app/Contents/MacOS/Blender', 'blender'].filter(Boolean);
  for (const candidate of candidates) {
    if (candidate === 'blender') return candidate;
    try { await access(candidate, constants.X_OK); return candidate; } catch {}
  }
  throw new Error('Blender executable not found');
}

function exec(command, args) {
  return new Promise((resolvePromise, reject) => {
    execFile(command, args, { maxBuffer: 1024 * 1024 }, (error, stdout, stderr) => {
      if (error) { reject(new Error(`${stdout}${stderr}${error.message}`)); return; }
      resolvePromise(`${stdout}${stderr}`);
    });
  });
}

function parseBlenderVersion(output) {
  const line = key => output.split('\n').find(item => item.trimStart().startsWith(`${key}:`))?.split(':').slice(1).join(':').trim() ?? null;
  return { version: output.split('\n').find(Boolean)?.trim() ?? null, buildHash: line('build hash'), buildBranch: line('build branch'), buildPlatform: line('build platform'), buildType: line('build type') };
}

function failed(reason, observed, expected = null, checks = []) {
  return { documentType: 'BFS_COMPILE_RECEIPT_VERIFICATION', version: '0.1.0', valid: false, reason, observed, expected, checks };
}

export async function verifyCompileReceipt(receiptPath) {
  const checks = [];
  try {
    const receiptFile = await trustedRepositoryFile(relative(repositoryRoot, resolve(receiptPath)), 'CompileReceipt');
    const receipt = JSON.parse(await readFile(receiptFile, 'utf8'));
    if (receipt.documentType !== 'BFS_COMPILE_RECEIPT' || receipt.version !== '0.1.0') return failed('RECEIPT_TYPE', `${receipt.documentType}@${receipt.version}`, 'BFS_COMPILE_RECEIPT@0.1.0', checks);
    const receiptBody = structuredClone(receipt);
    delete receiptBody.receiptHash;
    const computedReceiptHash = sha256Canonical(receiptBody);
    if (computedReceiptHash !== receipt.receiptHash) return failed('RECEIPT_SELF_HASH', computedReceiptHash, receipt.receiptHash, checks);
    checks.push('RECEIPT_SELF_HASH');
    const computedIdentityHash = sha256Canonical(receipt.executionIdentity);
    if (computedIdentityHash !== receipt.executionIdentityHash) return failed('EXECUTION_IDENTITY_HASH', computedIdentityHash, receipt.executionIdentityHash, checks);
    checks.push('EXECUTION_IDENTITY_HASH');

    const planPath = await trustedRepositoryFile(receipt.executionIdentity.buildPlan.uri, 'BuildPlan');
    const planMetadata = await stat(planPath);
    const planFileSha = await sha256File(planPath);
    if (planFileSha !== receipt.executionIdentity.buildPlan.sha256 || planMetadata.size !== receipt.executionIdentity.buildPlan.bytes) return failed('PLAN_FILE_SHA', { sha256: planFileSha, bytes: planMetadata.size }, { sha256: receipt.executionIdentity.buildPlan.sha256, bytes: receipt.executionIdentity.buildPlan.bytes }, checks);
    checks.push('PLAN_FILE_SHA');
    const wrapper = JSON.parse(await readFile(planPath, 'utf8'));
    const computedPlanHash = sha256Bytes(canonicalJson(wrapper.plan));
    if (computedPlanHash !== wrapper.planHash) return failed('PLAN_SELF_HASH', computedPlanHash, wrapper.planHash, checks);
    if (wrapper.planHash !== receipt.executionIdentity.buildPlan.planHash) return failed('PLAN_HASH_BINDING', wrapper.planHash, receipt.executionIdentity.buildPlan.planHash, checks);
    checks.push('PLAN_HASH_BINDING');

    const expectedToolUris = {
      sceneCompiler: 'blender/compile_scene.py',
      restrictedCli: 'scripts/run-restricted-blender-compile.mjs',
      budgetSupervisor: 'scripts/lib/budgeted-process.mjs',
      receiptGenerator: 'scripts/lib/compile-receipt.mjs',
      receiptFormat: 'scripts/lib/receipt-format.mjs',
    };
    for (const [field, expectedUri] of Object.entries(expectedToolUris)) {
      if (receipt.executionIdentity.tools[field]?.uri !== expectedUri) return failed('TOOL_URI_BINDING', receipt.executionIdentity.tools[field]?.uri, expectedUri, checks);
    }
    if (receipt.executionIdentity.configuration.budgetProfile?.uri !== 'specs/restricted-compile-budget.v0.1.json') return failed('BUDGET_PROFILE_URI_BINDING', receipt.executionIdentity.configuration.budgetProfile?.uri, 'specs/restricted-compile-budget.v0.1.json', checks);
    if (receipt.executionIdentity.configuration.ocio?.uri !== wrapper.plan.outputSpec.color.ocioConfigUri) return failed('OCIO_URI_BINDING', receipt.executionIdentity.configuration.ocio?.uri, wrapper.plan.outputSpec.color.ocioConfigUri, checks);
    checks.push('TRUSTED_URIS');

    for (const [field, reason, label] of [
      ['sceneCompiler', 'COMPILER_SHA', 'Scene compiler'],
      ['restrictedCli', 'RESTRICTED_CLI_SHA', 'Restricted CLI'],
      ['budgetSupervisor', 'BUDGET_SUPERVISOR_SHA', 'Budget supervisor'],
      ['receiptGenerator', 'RECEIPT_GENERATOR_SHA', 'Receipt generator'],
      ['receiptFormat', 'RECEIPT_FORMAT_SHA', 'Receipt format'],
    ]) {
      const identity = receipt.executionIdentity.tools[field];
      const path = await trustedRepositoryFile(identity.uri, label);
      const metadata = await stat(path);
      const observed = await sha256File(path);
      if (observed !== identity.sha256 || metadata.size !== identity.bytes) return failed(reason, { sha256: observed, bytes: metadata.size }, { sha256: identity.sha256, bytes: identity.bytes }, checks);
      checks.push(reason);
    }

    for (const [field, reason, label] of [
      ['budgetProfile', 'BUDGET_PROFILE_SHA', 'Budget profile'],
      ['ocio', 'OCIO_SHA', 'OCIO config'],
    ]) {
      const identity = receipt.executionIdentity.configuration[field];
      const path = await trustedRepositoryFile(identity.uri, label);
      const metadata = await stat(path);
      const observed = await sha256File(path);
      if (observed !== identity.sha256 || metadata.size !== identity.bytes) return failed(reason, { sha256: observed, bytes: metadata.size }, { sha256: identity.sha256, bytes: identity.bytes }, checks);
      checks.push(reason);
    }

    const blenderPath = resolve(await findBlender());
    const blenderMetadata = await stat(blenderPath);
    const blenderSha = await sha256File(blenderPath);
    if (blenderSha !== receipt.executionIdentity.runtime.blender.sha256 || blenderMetadata.size !== receipt.executionIdentity.runtime.blender.bytes) return failed('BLENDER_BINARY_SHA', { sha256: blenderSha, bytes: blenderMetadata.size }, { sha256: receipt.executionIdentity.runtime.blender.sha256, bytes: receipt.executionIdentity.runtime.blender.bytes }, checks);
    const blenderVersion = parseBlenderVersion(await exec(blenderPath, ['--version']));
    if (blenderVersion.buildHash !== receipt.executionIdentity.runtime.blender.buildHash) return failed('BLENDER_BUILD_IDENTITY', blenderVersion.buildHash, receipt.executionIdentity.runtime.blender.buildHash, checks);
    checks.push('BLENDER_BINARY_SHA');

    const nodeMetadata = await stat(process.execPath);
    const nodeSha = await sha256File(process.execPath);
    if (nodeSha !== receipt.executionIdentity.runtime.node.sha256 || nodeMetadata.size !== receipt.executionIdentity.runtime.node.bytes) return failed('NODE_BINARY_SHA', { sha256: nodeSha, bytes: nodeMetadata.size }, { sha256: receipt.executionIdentity.runtime.node.sha256, bytes: receipt.executionIdentity.runtime.node.bytes }, checks);
    if (process.version !== receipt.executionIdentity.runtime.node.version) return failed('NODE_VERSION', process.version, receipt.executionIdentity.runtime.node.version, checks);
    checks.push('NODE_BINARY_SHA');

    const artifactChecks = [
      ['budgetReport', 'BUDGET_REPORT_SHA', 'Budget report'],
      ['sceneManifest', 'MANIFEST_SHA', 'Scene manifest'],
      ['sceneStructureCanonical', 'STRUCTURE_CANONICAL_SHA', 'Canonical scene structure'],
      ['sceneBlend', 'BLEND_SHA', 'Scene blend'],
    ];
    const artifactPaths = {};
    for (const [field, reason, label] of artifactChecks) {
      const identity = receipt.run[field];
      const path = await trustedRepositoryFile(identity.uri, label);
      const metadata = await stat(path);
      const observed = await sha256File(path);
      if (observed !== identity.sha256 || metadata.size !== identity.bytes) return failed(reason, { sha256: observed, bytes: metadata.size }, { sha256: identity.sha256, bytes: identity.bytes }, checks);
      artifactPaths[field] = path;
      checks.push(reason);
    }

    const budgetReport = JSON.parse(await readFile(artifactPaths.budgetReport, 'utf8'));
    if (budgetReport.outcome !== 'PASS' || receipt.run.budgetReport.outcome !== 'PASS') return failed('BUDGET_OUTCOME_BINDING', budgetReport.outcome, 'PASS', checks);
    if (!isDeepStrictEqual(budgetReport.metrics, receipt.run.budgetReport.metrics) || budgetReport.budgetProfile?.sha256 !== receipt.executionIdentity.configuration.budgetProfile.sha256) return failed('BUDGET_REPORT_BINDING', { metrics: budgetReport.metrics, profile: budgetReport.budgetProfile?.sha256 }, { metrics: receipt.run.budgetReport.metrics, profile: receipt.executionIdentity.configuration.budgetProfile.sha256 }, checks);
    const manifest = JSON.parse(await readFile(artifactPaths.sceneManifest, 'utf8'));
    if (manifest.execution?.planHash !== receipt.executionIdentity.buildPlan.planHash || receipt.run.sceneManifest.planHash !== receipt.executionIdentity.buildPlan.planHash) return failed('MANIFEST_PLAN_BINDING', manifest.execution?.planHash, receipt.executionIdentity.buildPlan.planHash, checks);
    if (manifest.execution?.ocioConfigSha256 !== receipt.executionIdentity.configuration.ocio.sha256) return failed('MANIFEST_OCIO_BINDING', manifest.execution?.ocioConfigSha256, receipt.executionIdentity.configuration.ocio.sha256, checks);
    if (manifest.execution?.blender?.buildHash !== receipt.executionIdentity.runtime.blender.buildHash) return failed('MANIFEST_BLENDER_BINDING', manifest.execution?.blender?.buildHash, receipt.executionIdentity.runtime.blender.buildHash, checks);
    const canonicalStructureBytes = await readFile(artifactPaths.sceneStructureCanonical);
    const structureHash = sha256Bytes(canonicalStructureBytes);
    if (!isDeepStrictEqual(JSON.parse(canonicalStructureBytes), manifest.structure)) return failed('MANIFEST_STRUCTURE_CONTENT', 'parsed canonical structure differs from manifest structure', 'deep equality', checks);
    if (structureHash !== manifest.structureHash || structureHash !== manifest.structureCanonical?.sha256 || receipt.run.sceneManifest.structureHash !== manifest.structureHash || receipt.run.sceneStructureCanonical.structureHash !== manifest.structureHash) return failed('MANIFEST_STRUCTURE_BINDING', structureHash, receipt.run.sceneManifest.structureHash, checks);
    checks.push('MANIFEST_BINDINGS');
    return { documentType: 'BFS_COMPILE_RECEIPT_VERIFICATION', version: '0.1.0', valid: true, reason: 'OK', receiptHash: receipt.receiptHash, executionIdentityHash: receipt.executionIdentityHash, planHash: wrapper.planHash, structureHash: manifest.structureHash, checks };
  } catch (error) {
    return failed('VERIFIER_ERROR', error.message, null, checks);
  }
}

async function main() {
  const args = process.argv.slice(2);
  const option = name => { const index = args.indexOf(name); return index >= 0 ? args[index + 1] : null; };
  const receipt = option('--receipt');
  const report = option('--report');
  if (!receipt) throw new Error('Usage: --receipt FILE [--report FILE]');
  const result = await verifyCompileReceipt(receipt);
  if (report) await writeFile(await trustedRepositoryOutput(report, 'Receipt verifier report'), `${JSON.stringify(result, null, 2)}\n`);
  process.stdout.write(`BFS_RECEIPT_VERIFY ${result.valid ? 'PASS' : 'FAIL'} ${result.reason}\n`);
  if (!result.valid) process.exitCode = 1;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch(error => { process.stderr.write(`BFS_RECEIPT_VERIFY_ERROR ${error.message}\n`); process.exitCode = 1; });
}

#!/usr/bin/env node

import { spawn } from 'node:child_process';
import { mkdtemp, readFile, readdir, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { isDeepStrictEqual } from 'node:util';
import { runGit } from './lib/formal-run-admission.mjs';
import {
  canonicalHash,
  canonicalJson,
  repoUri,
  resolveExistingRepositoryPath,
  sha256Bytes,
  sha256File,
  sortValue,
  validSelfHash,
} from './lib/production-compile-receipt.mjs';
import { repositoryRoot } from './lib/scene-spec.mjs';

const BLENDER = '/Applications/Blender.app/Contents/MacOS/Blender';

function parseArguments(argv) {
  if (argv.length !== 2 || argv[0] !== '--receipt') throw new Error('Usage: --receipt RELATIVE_PRODUCTION_RECEIPT');
  return { receipt: argv[1] };
}

async function runChild(command, args) {
  const child = spawn(command, args, {
    cwd: repositoryRoot,
    env: { PATH: '/opt/homebrew/bin:/usr/bin:/bin', LANG: 'C.UTF-8', LC_ALL: 'C.UTF-8' },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  const stdout = [];
  const stderr = [];
  child.stdout.on('data', chunk => stdout.push(chunk));
  child.stderr.on('data', chunk => stderr.push(chunk));
  const completion = await new Promise((resolvePromise, reject) => {
    child.on('error', reject);
    child.on('close', (exitCode, signal) => resolvePromise({ exitCode, signal }));
  });
  return { pid: child.pid, ...completion, stdout: Buffer.concat(stdout).toString('utf8'), stderr: Buffer.concat(stderr).toString('utf8') };
}

async function requireIdentity(identity, label) {
  const filePath = await resolveExistingRepositoryPath(identity?.uri, label);
  const observed = await sha256File(filePath);
  if (observed !== identity.sha256) throw new Error(`${label} file hash mismatch`);
  return filePath;
}

function requireRecord(record, schemaVersion, hashField, label) {
  if (record?.schemaVersion !== schemaVersion) throw new Error(`${label} schema mismatch`);
  if (!validSelfHash(record, hashField)) throw new Error(`${label} self-hash mismatch`);
  return record;
}

async function verifyGitEvidence(admission, checks) {
  const commit = admission.evidence?.evidenceCommit;
  if (!/^[0-9a-f]{40}$/.test(commit ?? '')) throw new Error('Admission evidence commit is invalid');
  const ancestor = await runGit(['merge-base', '--is-ancestor', commit, 'origin/main'], repositoryRoot);
  if (ancestor.exitCode !== 0) throw new Error('Admission evidence commit is not pushed to origin/main');
  checks.push('PREFLIGHT_EVIDENCE_PUSHED');
}

async function invokeCurrentReceiptVerifier(compileReceiptPath) {
  const moduleUri = pathToFileURL(resolve(repositoryRoot, 'scripts/verify-compile-receipt.mjs')).href;
  const source = `const moduleValue=await import(${JSON.stringify(moduleUri)});const result=await moduleValue.verifyCompileReceipt(process.argv[1]);process.stdout.write(JSON.stringify(result));`;
  const child = await runChild(process.execPath, ['--input-type=module', '-e', source, compileReceiptPath]);
  if (child.exitCode !== 0 || child.signal !== null) throw new Error(`Current CompileReceipt verifier process failed: ${child.stderr}`);
  const result = JSON.parse(child.stdout);
  if (!result.valid || result.reason !== 'OK' || result.checks?.length !== 19) throw new Error('Current CompileReceipt verifier did not pass exactly 19 checks');
  return { child: { pid: child.pid, exitCode: child.exitCode, signal: child.signal }, result };
}

async function invokeBlendAudit(blendPath) {
  const scratch = await mkdtemp(join(tmpdir(), 'bfs-production-verifier-'));
  const reportPath = join(scratch, 'blend-audit.json');
  try {
    const child = await runChild(BLENDER, [
      '--background', '--factory-startup', '--disable-autoexec', '--python-exit-code', '1',
      '--python', resolve(repositoryRoot, 'blender/audit_compiled_artifact.py'), '--',
      '--input', blendPath, '--output', reportPath,
    ]);
    if (child.exitCode !== 0 || child.signal !== null) throw new Error(`Compiled .blend audit failed: ${child.stderr || child.stdout}`);
    return { child: { pid: child.pid, exitCode: child.exitCode, signal: child.signal }, result: JSON.parse(await readFile(reportPath, 'utf8')) };
  } finally {
    await rm(scratch, { recursive: true, force: true });
  }
}

async function verify(receiptUri) {
  const checks = [];
  const receiptPath = await resolveExistingRepositoryPath(receiptUri, 'Production receipt');
  const outputRoot = dirname(receiptPath);
  const receipt = JSON.parse(await readFile(receiptPath, 'utf8'));
  if (receipt.schemaVersion !== 'bfs.productionCompileReceipt.v0.2' || receipt.status !== 'PASS') throw new Error('Production receipt schema or status mismatch');
  if (!validSelfHash(receipt, 'receiptHash')) throw new Error('Production receipt self-hash mismatch');
  checks.push('PRODUCTION_RECEIPT_SELF_HASH');

  const releasePath = await requireIdentity(receipt.release, 'Release manifest');
  const release = JSON.parse(await readFile(releasePath, 'utf8'));
  if (release.schemaVersion !== 'bfs.productionCompilerEntry.v0.2' || release.releaseId !== receipt.release.releaseId) throw new Error('Release manifest binding mismatch');
  for (const [uri, expectedSha256] of Object.entries(release.frozenFiles).sort(([left], [right]) => left.localeCompare(right))) {
    const filePath = await resolveExistingRepositoryPath(uri, `Frozen release file ${uri}`);
    if (await sha256File(filePath) !== expectedSha256) throw new Error(`Frozen release file mismatch: ${uri}`);
  }
  const packageDocument = JSON.parse(await readFile(resolve(repositoryRoot, 'package.json'), 'utf8'));
  for (const [key, value] of Object.entries(release.packageAliases)) {
    if (packageDocument.scripts?.[key] !== value) throw new Error(`Preferred package alias mismatch: ${key}`);
  }
  checks.push('RELEASE_AND_PACKAGE_BINDINGS');

  const preflightPath = await requireIdentity(receipt.authorization.preflight, 'Production preflight');
  const attemptPath = await requireIdentity(receipt.authorization.attempt, 'Production attempt');
  const admissionPath = await requireIdentity(receipt.authorization.admission, 'Production admission');
  const attemptReceiptPath = await requireIdentity(receipt.authorization.attemptReceipt, 'Production attempt receipt');
  const formalStartPath = await requireIdentity(receipt.authorization.formalStart, 'Production formal start');
  const preflight = requireRecord(JSON.parse(await readFile(preflightPath, 'utf8')), 'bfs.productionCompilePreflight.v0.1', 'preflightHash', 'Production preflight');
  const attempt = requireRecord(JSON.parse(await readFile(attemptPath, 'utf8')), 'bfs.productionCompileAttempt.v0.1', 'attemptHash', 'Production attempt');
  const admission = requireRecord(JSON.parse(await readFile(admissionPath, 'utf8')), 'bfs.productionCompileAdmission.v0.1', 'admissionHash', 'Production admission');
  const attemptReceipt = requireRecord(JSON.parse(await readFile(attemptReceiptPath, 'utf8')), 'bfs.productionCompileAttemptReceipt.v0.1', 'receiptHash', 'Production attempt receipt');
  const formalStart = requireRecord(JSON.parse(await readFile(formalStartPath, 'utf8')), 'bfs.productionCompileFormalStart.v0.1', 'formalStartHash', 'Production formal start');
  if (preflight.status !== 'ACCEPTED' || admission.status !== 'ACCEPTED' || attemptReceipt.status !== 'ACCEPTED' || formalStart.status !== 'AUTHORIZED') throw new Error('Authorization status mismatch');
  if (attempt.sequence !== 1 || admission.sequence !== 2 || attemptReceipt.sequence !== 3 || formalStart.sequence !== 4) throw new Error('Authorization sequence mismatch');
  if (attempt.preflight.sha256 !== receipt.authorization.preflight.sha256 || admission.evidence?.preflight?.preflightHash !== preflight.preflightHash
    || admission.attempt.attemptHash !== attempt.attemptHash || attemptReceipt.attempt.attemptHash !== attempt.attemptHash || attemptReceipt.admission.admissionHash !== admission.admissionHash
    || formalStart.attemptReceipt.receiptHash !== attemptReceipt.receiptHash) throw new Error('Authorization cross-binding mismatch');
  if (preflight.invocation.outputRoot !== receipt.output.root || admission.output.repositoryRelative !== receipt.output.root
    || formalStart.outputRoot !== receipt.output.root || repoUri(outputRoot) !== receipt.output.root) throw new Error('Authorization output binding mismatch');
  await verifyGitEvidence(admission, checks);
  checks.push('AUTHORIZATION_SEQUENCE_AND_BINDINGS');

  const sceneSpecPath = await requireIdentity(receipt.source, 'Production SceneSpec');
  if (repoUri(sceneSpecPath) !== preflight.source.uri || receipt.source.sha256 !== preflight.source.sha256) throw new Error('SceneSpec preflight binding mismatch');
  const planPath = await requireIdentity(receipt.buildPlan, 'Production BuildPlan');
  const wrapper = JSON.parse(await readFile(planPath, 'utf8'));
  if (sha256Bytes(Buffer.from(canonicalJson(wrapper.plan))) !== wrapper.planHash || wrapper.planHash !== receipt.buildPlan.planHash
    || wrapper.planHash !== preflight.buildPlan.planHash) throw new Error('BuildPlan binding mismatch');
  checks.push('SCENE_AND_BUILD_PLAN_BINDINGS');

  const diskAdmissionPath = await requireIdentity(receipt.authorization.nativeCompileDiskAdmission, 'Native compile disk admission');
  const diskAdmission = requireRecord(JSON.parse(await readFile(diskAdmissionPath, 'utf8')), 'bfs.productionNativeCompileDiskAdmission.v0.1', 'diskAdmissionHash', 'Native compile disk admission');
  if (diskAdmission.sequence !== 5 || diskAdmission.status !== 'ACCEPTED' || diskAdmission.disk?.status !== 'PASS'
    || diskAdmission.policy?.minimumReserveBytes !== '107374182400' || diskAdmission.policy?.projectedWriteBytes !== '536870912'
    || diskAdmission.policy?.overrideAllowedByReleaseEntry !== false
    || BigInt(diskAdmission.effectiveAvailableBytes) > BigInt(diskAdmission.filesystemAvailableBytesObserved)
    || diskAdmission.restrictedCompilerProcessesStarted !== 0 || diskAdmission.nativeBlenderProcessesStarted !== 0) {
    throw new Error('Native compile disk readmission mismatch');
  }
  checks.push('NATIVE_COMPILE_DISK_READMISSION');

  const budgetPath = await requireIdentity(receipt.restrictedCompile.budgetReport, 'Budget report');
  const compileReceiptPath = await requireIdentity(receipt.restrictedCompile.compileReceipt, 'Current CompileReceipt');
  const manifestPath = await requireIdentity(receipt.restrictedCompile.sceneManifest, 'Scene manifest');
  const structurePath = await requireIdentity(receipt.restrictedCompile.sceneStructureCanonical, 'Canonical scene structure');
  const blendPath = await requireIdentity(receipt.restrictedCompile.sceneBlend, 'Compiled .blend');
  const budget = JSON.parse(await readFile(budgetPath, 'utf8'));
  if (budget.documentType !== 'BFS_BUDGETED_PROCESS_RESULT' || budget.version !== '0.2.0' || budget.outcome !== 'PASS'
    || budget.command !== BLENDER || budget.child?.exitCode !== 0 || budget.child?.signal !== null || budget.child?.spawnError !== null
    || !Number.isSafeInteger(budget.child?.pid) || budget.child.pid <= 0 || budget.child.pid === receipt.restrictedCompile.wrapperProcess.pid) {
    throw new Error('Native budget/PID receipt mismatch');
  }
  checks.push('NATIVE_BUDGET_PID_BINDING');

  const currentVerification = await invokeCurrentReceiptVerifier(compileReceiptPath);
  if (currentVerification.result.planHash !== wrapper.planHash) throw new Error('Current verifier plan binding mismatch');
  checks.push('CURRENT_COMPILE_RECEIPT_19_CHECKS');

  const manifest = JSON.parse(await readFile(manifestPath, 'utf8'));
  const structureBytes = await readFile(structurePath);
  const structureHash = sha256Bytes(structureBytes);
  if (structureHash !== manifest.structureHash || structureHash !== receipt.restrictedCompile.sceneStructureCanonical.structureHash
    || !isDeepStrictEqual(JSON.parse(structureBytes), manifest.structure)) throw new Error('Canonical structure binding mismatch');
  checks.push('MANIFEST_AND_STRUCTURE_BINDINGS');

  const blendAudit = await invokeBlendAudit(blendPath);
  if (blendAudit.result.documentType !== 'BFS_COMPILED_BLEND_AUDIT' || blendAudit.result.version !== '0.1.0'
    || blendAudit.result.scene?.planHash !== wrapper.planHash || blendAudit.result.scene?.structureHash !== structureHash
    || blendAudit.result.scene?.manifestVersion !== manifest.manifestVersion || blendAudit.result.blender?.buildHash !== release.runtime.blender.buildHash) {
    throw new Error('Compiled .blend embedded binding mismatch');
  }
  checks.push('BLEND_EMBEDDED_BINDINGS');

  const rootRoster = (await readdir(outputRoot)).sort();
  const restrictedRoot = dirname(budgetPath);
  const restrictedRoster = (await readdir(restrictedRoot)).sort();
  if (!isDeepStrictEqual(rootRoster, receipt.output.expectedRootRoster) || !isDeepStrictEqual(restrictedRoster, receipt.output.expectedRestrictedRoster)) {
    throw new Error('Production output roster mismatch');
  }
  checks.push('OUTPUT_ROSTER_EXACT');

  const body = {
    schemaVersion: 'bfs.productionCompileVerification.v0.1',
    valid: true,
    reason: 'OK',
    receipt: { uri: receiptUri, sha256: await sha256File(receiptPath), receiptHash: receipt.receiptHash },
    planHash: wrapper.planHash,
    structureHash,
    nativeChildPid: budget.child.pid,
    checks,
    verifierPid: process.pid,
    currentCompileReceiptVerification: currentVerification.result,
    blendAudit: blendAudit.result,
    children: { currentReceiptVerifier: currentVerification.child, blendArtifactAudit: blendAudit.child },
    operations: { renderCalls: 0, modelCalls: 0, networkCalls: 0, dockerProcesses: 0 },
  };
  return { ...body, verificationHash: canonicalHash(body) };
}

export async function verifyProductionCompileReceipt(argv) {
  let result;
  try {
    const parsed = parseArguments(argv);
    result = await verify(parsed.receipt);
  } catch (error) {
    const body = {
      schemaVersion: 'bfs.productionCompileVerification.v0.1',
      valid: false,
      reason: error?.message ?? String(error),
      checks: [],
      operations: { renderCalls: 0, modelCalls: 0, networkCalls: 0, dockerProcesses: 0 },
    };
    result = { ...body, verificationHash: canonicalHash(body) };
  }
  process.stdout.write(`BFS_PRODUCTION_RECEIPT_VERIFICATION_JSON ${JSON.stringify(sortValue(result))}\n`);
  process.stdout.write(`BFS_PRODUCTION_RECEIPT_VERIFY ${result.valid ? 'PASS' : 'FAIL'} ${result.reason}\n`);
  if (!result.valid) process.exitCode = 1;
  return result;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  verifyProductionCompileReceipt(process.argv.slice(2)).catch(error => {
    process.stderr.write(`BFS_PRODUCTION_RECEIPT_VERIFY_ERROR ${error.message}\n`);
    process.exitCode = 1;
  });
}
